106	// Function words that would otherwise crowd every ranking. The list is
107	// deliberately short and fixed: callers who need a different list can filter
108	// the full ranking (pass a large n) themselves.
109	const STOP_WORDS = new Set([
110	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
111	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
112	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
113	  'will', 'with',
114	]);
