116	/**
117	 * List the most frequent words in a piece of text.
118	 *
119	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
120	 * and stop words are skipped. Entries are ordered by count (highest first),
121	 * then alphabetically, so the result is deterministic.
122	 *
123	 * @param {string} text
124	 * @param {number} n How many entries to return; a non-negative integer.
125	 * @returns {Array<{word: string, count: number}>}
126	 */
127	function topWords(text, n) {
128	  assertText('topWords', text);
129	  if (!Number.isInteger(n) || n < 0) {
130	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
131	  }
132	  const counts = new Map();
133	  for (const token of tokenize(text)) {
134	    const word = token.toLowerCase().replace(/’/g, "'");
135	    if (STOP_WORDS.has(word)) {
136	      continue;
137	    }
138	    counts.set(word, (counts.get(word) ?? 0) + 1);
139	  }
140	  return [...counts]
141	    .map(([word, count]) => ({ word, count }))
142	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
143	    .slice(0, n);
144	}
