1	// A word is a run of letters or digits (any script), optionally joined to the
2	// next run by a single apostrophe (straight or typographic) or hyphen. The
3	// joiners are only part of a word when letters or digits sit on both sides, so
4	// a trailing "well-" or "dogs'" loses its joiner. Everything else, including
5	// em dashes, periods and underscores, separates words.
6	const WORD_PATTERN = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu;
7	
8	function assertText(fn, value) {
9	  if (typeof value !== 'string') {
10	    throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
11	  }
12	}
13	
14	// Private: the single definition of "word" shared by every statistic below.
15	function tokenize(text) {
16	  return text.match(WORD_PATTERN) ?? [];
17	}
18	
19	/**
20	 * Count the words in a piece of text.
21	 *
22	 * @param {string} text
23	 * @returns {number}
24	 */
25	function wordCount(text) {
26	  assertText('wordCount', text);
27	  return tokenize(text).length;
28	}
29	
30	// Words whose trailing period does not end a sentence. Compared lower-case and
31	// without any opening bracket or quote. "U.S.A." style initialisms are not
32	// listed: they usually do end a sentence when they come last, and guessing
33	// otherwise would trade one error for another.
34	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
35	
36	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
37	// only where whitespace or the end of the text follows. Requiring that keeps
38	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
39	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
40	
41	function endsWithAbbreviation(before) {
42	  const last = before.match(/(\S+)$/);
43	  if (last === null) {
44	    return false;
45	  }
46	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
47	  return ABBREVIATIONS.has(word);
48	}
49	
50	/**
51	 * Count the sentences in a piece of text.
52	 *
53	 * A sentence is a stretch of text containing at least one word and ending at a
54	 * terminator run, or at the end of the text. A lone period after a known
55	 * abbreviation does not end a sentence.
56	 *
57	 * @param {string} text
58	 * @returns {number}
59	 */
60	function sentenceCount(text) {
61	  assertText('sentenceCount', text);
62	  let count = 0;
63	  let start = 0;
64	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
65	    const before = text.slice(start, match.index);
66	    if (match[1] === '.' && endsWithAbbreviation(before)) {
67	      continue;
68	    }
69	    if (tokenize(before).length > 0) {
70	      count += 1;
71	    }
72	    start = match.index + match[0].length;
73	  }
74	  if (tokenize(text.slice(start)).length > 0) {
75	    count += 1;
76	  }
77	  return count;
78	}
79	
80	module.exports = { wordCount, sentenceCount };
